"use strict";(globalThis.webpackChunksentinel_docs=globalThis.webpackChunksentinel_docs||[]).push([[9584],{25981(e){e.exports=JSON.parse('{"version":{"pluginId":"apis","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/apis/","label":"\ud83c\udf10 Sentinel Public APIs","docId":"README","unlisted":false},{"type":"link","href":"/apis/rpc/","label":"\ud83d\udce1 RPC Gateway","docId":"rpc/README","unlisted":false},{"type":"category","label":"\u26a1 Interacting with gRPC","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/apis/grpc/interact-grpc-curl","label":"gRPCurl","docId":"grpc/interact-grpc-curl","unlisted":false},{"type":"link","href":"/apis/grpc/interact-grpc-buf-studio","label":"Protobuf schema & Buf","docId":"grpc/interact-grpc-buf-studio","unlisted":false},{"type":"link","href":"/apis/grpc/interact-grpc-go","label":"gRPC Go","docId":"grpc/interact-grpc-go","unlisted":false}],"href":"/apis/grpc/"},{"type":"link","href":"/apis/interact-rest","label":"\ud83d\udd0c Rest Endpoints","docId":"interact-rest","unlisted":false}]},"docs":{"grpc/interact-grpc-buf-studio":{"id":"grpc/interact-grpc-buf-studio","title":"Protobuf schema & Buf","description":"The Sentinel Protobuf schema is published to the Buf Schema Registry as the module sentinel-official/sentinelhub. Browsing it there is the fastest way to read the full type graph: every service, method, message and enum, with the comments from the source .proto files.","sidebar":"tutorialSidebar"},"grpc/interact-grpc-curl":{"id":"grpc/interact-grpc-curl","title":"gRPCurl","description":"grpcurl is curl for gRPC. It is the quickest way to explore the chain: because the hub answers reflection requests, grpcurl can discover every service and message type on its own, with no .proto files on your machine. Install it by following the instructions in the link above.","sidebar":"tutorialSidebar"},"grpc/interact-grpc-go":{"id":"grpc/interact-grpc-go","title":"gRPC Go","description":"This page shows how to query the chain, and how to broadcast a transaction, from a Go program. The pattern is the same in both cases: open a gRPC connection, then use the Protobuf-generated client for the service you want.","sidebar":"tutorialSidebar"},"grpc/README":{"id":"grpc/README","title":"Interacting with gRPC","description":"The Sentinel Hub runs a gRPC server alongside its RPC and LCD endpoints. Every module (the Cosmos SDK ones, IBC, CosmWasm and Sentinel\'s own) publishes a Protobuf query service on it, and the server answers reflection requests, so any gRPC client can discover the whole API without being given a schema file first.","sidebar":"tutorialSidebar"},"interact-rest":{"id":"interact-rest","title":"Rest Endpoints","description":"Using the REST endpoints","sidebar":"tutorialSidebar"},"README":{"id":"README","title":"Sentinel Public APIs","description":"There are currently three public interfaces to the Sentinel Hub: RPC, gRPC and LCD.","sidebar":"tutorialSidebar"},"rpc/README":{"id":"rpc/README","title":"RPC Gateway","description":"The RPC interface is served by CometBFT v0.37, the consensus engine bundled with hub v12. Unlike the LCD REST API, its endpoints are generic: rather than one route per module query, they expose the consensus engine itself, meaning blocks, transactions, validators, the mempool and the ABCI interface. It is also the only interface that can broadcast a transaction to the mempool.","sidebar":"tutorialSidebar"}}}}')}}]);